# shellcheck shell=bash
# micro colorschemes, one per variant. Syntax groups follow palette/syntax.json roles.
# Output: ports/micro/terminal-noir.micro, ports/micro/terminal-noir-paper.micro

build_micro() {
    local v file
    for v in dark light; do
        file="terminal-noir$([ "$v" = light ] && echo -paper || true).micro"
        jq -r --arg v "$v" '
            .variants[$v] as $c
            | def l($k; $x): "color-link \($k) \"\($x)\"";
            "# Terminal Noir (\($v)) for micro. https://terminalnoir.web.app",
            "# Generated by scripts/build from palette/palette.json.",
            "",
            l("default"; "\($c.text.primary),\($c.surface.base)"),
            l("comment"; $c.text.muted),
            l("identifier"; $c.accent.info),
            l("identifier.class"; $c.ansi.bright.magenta),
            l("identifier.var"; $c.text.primary),
            l("constant"; $c.accent.warning),
            l("constant.number"; $c.accent.warning),
            l("constant.bool"; $c.accent.warning),
            l("constant.string"; $c.accent.success),
            l("constant.string.char"; $c.accent.success),
            l("constant.specialChar"; $c.ansi.bright.cyan),
            l("statement"; $c.accent.primary),
            l("symbol"; $c.text.primary),
            l("symbol.operator"; $c.text.primary),
            l("symbol.brackets"; $c.text.primary),
            l("symbol.tag"; $c.ansi.normal.red),
            l("preproc"; $c.ansi.bright.magenta),
            l("type"; $c.ansi.bright.magenta),
            l("type.keyword"; $c.accent.primary),
            l("special"; $c.ansi.bright.cyan),
            l("underlined"; $c.accent.info),
            l("error"; "bold \($c.accent.error)"),
            l("todo"; "bold \($c.accent.warning)"),
            l("hlsearch"; "\($c.accent.onPrimary),\($c.accent.warning)"),
            l("statusline"; "\($c.text.primary),\($c.surface.elevated)"),
            l("statusline.inactive"; "\($c.text.muted),\($c.surface.raised)"),
            l("tabbar"; "\($c.text.muted),\($c.surface.raised)"),
            l("tabbar.active"; "\($c.accent.onPrimary),\($c.accent.primary)"),
            l("indent-char"; $c.surface.border),
            l("line-number"; "\($c.text.faint),\($c.surface.base)"),
            l("current-line-number"; "\($c.accent.primary),\($c.surface.raised)"),
            l("cursor-line"; $c.surface.raised),
            l("color-column"; $c.surface.raised),
            l("gutter-error"; $c.accent.error),
            l("gutter-warning"; $c.accent.warning),
            l("diff-added"; $c.accent.success),
            l("diff-modified"; $c.accent.warning),
            l("diff-deleted"; $c.accent.error),
            l("match-brace"; "\($c.accent.onPrimary),\($c.accent.primary)"),
            l("selection"; "\($c.text.primary),\($c.surface.selection)"),
            l("divider"; "\($c.surface.outline),\($c.surface.base)"),
            l("scrollbar"; "\($c.surface.outline),\($c.surface.raised)"),
            l("message"; $c.text.primary),
            l("error-message"; $c.accent.error)' "$PALETTE" > "$OUT/ports/micro/$file"
    done
}
